<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import PlanComparison from './PlanComparison.vue'
import { api, json, type PlanState, type Proposal, type Plan, type Exercise, type AIUsage } from '../api'
const props=defineProps<{today:string;refreshToken:number}>(),emit=defineEmits<{changed:[]}>()
const state=ref<PlanState|null>(null),versions=ref<Plan[]>([]),exercises=ref<Exercise[]>([]),selected=ref<Proposal|null>(null),busy=ref(false),error=ref(''),start=ref(props.today),notice=ref('')
const evidence=ref<Record<string,unknown>|null>(null)
const evidenceLabels:Record<string,string>={id:'记录 ID',type:'类型',date:'日期',title:'标题',distance_m:'距离（米）',duration_seconds:'时长（秒）',status:'完成情况',effort:'主观用力',notes:'备注',pain_notes:'疼痛反馈',fatigue:'疲劳',soreness_level:'酸胀程度',soreness_location:'酸胀部位',pain_level:'疼痛程度',pain_location:'疼痛部位',training_readiness:'训练意愿',function_affected:'日常活动受影响',illness_notes:'疾病反馈',exercises:'实际动作组'}
async function viewEvidence(id:string){error.value='';try{evidence.value=await api<Record<string,unknown>>(`/plan-evidence/${id}`)}catch(e){error.value=(e as Error).message}}
const ai=ref<AIUsage|null>(null),allowExternal=ref(false)
const labels={run:'跑步',strength:'力量',recovery:'休息 / 恢复'}
async function load(){const [s,v,e,u]=await Promise.all([api<PlanState>('/plans/current'),api<Plan[]>('/plans/versions'),api<Exercise[]>('/exercises'),api<AIUsage>('/ai/usage')]);ai.value=u;state.value=s;versions.value=v;exercises.value=e;if(selected.value)selected.value=s.proposals.find(p=>p.id===selected.value?.id)||selected.value}
async function generate(){busy.value=true;error.value='';try{selected.value=await api<Proposal>('/plan-proposals',json('POST',{start_date:start.value,allow_external_ai:allowExternal.value}));await load();notice.value='仅生成了待确认草稿，正式计划尚未修改。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function approve(){if(!selected.value)return;busy.value=true;error.value='';try{await api(`/plan-proposals/${selected.value.id}/approve`,json('POST',{expected_plan_version:selected.value.base_version,expected_facts_revision:selected.value.facts_revision}));await load();notice.value='跑步与恢复已一起保存为新的正式版本。';emit('changed')}catch(e){error.value=(e as Error).message;await load()}finally{busy.value=false}}
async function reject(){if(!selected.value)return;busy.value=true;error.value='';try{await api(`/plan-proposals/${selected.value.id}/reject`,{method:'POST'});await load();notice.value='已拒绝草稿，正式计划保持原版本。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function restore(version:number){if(!state.value)return;busy.value=true;error.value='';try{const source=versions.value.find(v=>v.version===version);selected.value=await api<Proposal>('/plans/restore-proposal',json('POST',{source_version:version,start_date:source?.start_date||props.today,expected_plan_version:state.value.plan_version,expected_facts_revision:state.value.facts_revision}));await load();notice.value='恢复或撤回也需确认；原有训练事实不会删除。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch(()=>props.refreshToken,()=>load().catch(e=>error.value=(e as Error).message))
onMounted(()=>load().catch(e=>error.value=(e as Error).message))
</script>
<template><section class="card panelwide plan-panel"><div class="sectionhead"><div><h2>跑步与恢复</h2><p class="tiny muted">AI 跑步训练教练 · 提案先核对，确认才生效</p></div><span class="badge">{{state?.plan?`正式版本 ${state.plan_version}`:'尚无正式计划'}}</span></div><p class="evidence-note">{{ai?.provider==='deepseek'?'已配置 DeepSeek-V4.1-Flash；生成前需同意发送下述资料，结果仍需核对确认。':'当前计划生成使用模拟模板，非真实 AI 分析。'}} 训练规则未经过人工专业审阅；不提供膝痛康复处方。当前一般草稿只支持有限的轻强度安排，不用于比赛强化训练。</p><p v-if="state?.needs_review" class="error">有新的训练、身体反馈或日程，原计划需要重新评估；待确认的新草稿不会覆盖原版本。</p><ul v-if="state?.attention.length" class="plan-attention"><li v-for="a in state.attention" :key="a">{{a}}</li></ul><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="tiny" role="status">{{notice}}</p><label v-if="ai?.provider==='deepseek'" class="privacy-check"><input v-model="allowExternal" type="checkbox">同意将已保存档案（含身体情况和医生限制）、近期最多 10 次跑步（含已确认详细指标）、3 次身体反馈、当前计划及所选七天日程发送至 DeepSeek 生成草稿。不会发送原图、路线、账户或密码。</label><div class="plan-generate"><label class="field">一周开始日期<input v-model="start" type="date" :min="today" required></label><button class="btn primary" :disabled="busy||!start||(ai?.provider==='deepseek'&&!allowExternal)" @click="generate">{{busy?'处理中…':'生成 / 重新评估草稿'}}</button></div><div v-if="state?.plan && state.plan.scope!=='cycle'" class="plan-current"><h3>已确认七天安排</h3><p class="tiny muted">{{state.plan.summary}} · {{state.plan.is_mock?'模拟模板经你确认':'AI 草稿经你确认'}}</p><div v-for="s in state.plan.sessions.filter(s=>s.type!=='strength')" :key="s.id" class="plan-session"><div class="row"><b>{{s.date}} · {{s.title}}</b><span class="badge">{{labels[s.type]}}</span></div><p class="tiny muted">{{s.duration_minutes?s.duration_minutes+' 分钟':'无训练负荷'}} · {{s.purpose}}</p><div v-for="e in s.exercises" :key="e.exercise_id"><p class="tiny">{{exercises.find(x=>x.id===e.exercise_id)?.name||e.exercise_id}} · {{e.sets}} 组 × {{e.repetitions}} 次 · 休息 {{e.rest_seconds}} 秒 · 阻力：{{e.resistance}}</p><p class="tiny muted">{{exercises.find(x=>x.id===e.exercise_id)?.cues}} <a v-if="exercises.find(x=>x.id===e.exercise_id)" :href="exercises.find(x=>x.id===e.exercise_id)?.source" target="_blank" rel="noopener">说明 / 示范来源 ↗</a></p></div><details><summary class="tiny">替代 / 停止条件</summary><p class="tiny muted">{{s.stop_condition}}</p></details></div><button class="btn" :disabled="busy" @click="restore(0)">提出撤回训练安排</button></div><div v-if="state?.proposals.length" class="proposal-list"><h3>最近提案</h3><button v-for="p in state.proposals.filter(p=>p.scope!=='cycle')" :key="p.id" class="btn" :class="{primary:selected?.id===p.id}" @click="selected=p">{{p.start_date}} · {{p.state==='pending'?'待确认':p.state==='applied'?'已应用':p.state==='rejected'?'已拒绝':'已失效'}}</button></div><div v-if="selected" class="proposal-review"><div class="sectionhead"><h3>核对草稿与变化</h3><span class="badge">{{selected.is_mock?'模拟草稿':'AI 草稿'}} · {{selected.state}}</span></div><p>{{selected.summary}}</p><p class="tiny muted">{{selected.assessment}}</p><ul><li v-for="q in selected.questions" :key="q">{{q}}</li></ul><p v-for="u in selected.uncertainties" :key="u" class="tiny muted">{{u}}</p><PlanComparison v-if="selected.comparison" :comparison="selected.comparison"/><div v-for="change in selected.changes" :key="change.date" class="plan-change"><b>{{change.date}}</b><div class="change-grid"><div><span class="tiny muted">原安排</span><p v-for="s in change.before" :key="s.id" class="tiny">{{labels[s.type]}} · {{s.title}} · {{s.duration_minutes}} 分钟<template v-for="e in s.exercises" :key="e.exercise_id"><br>{{exercises.find(x=>x.id===e.exercise_id)?.name||e.exercise_id}} {{e.sets}} × {{e.repetitions}}，休息 {{e.rest_seconds}} 秒，阻力：{{e.resistance}}</template></p><p v-if="!change.before.length" class="tiny">无安排</p></div><div><span class="tiny muted">新安排</span><p v-for="s in change.after" :key="s.id" class="tiny">{{labels[s.type]}} · {{s.title}} · {{s.duration_minutes}} 分钟<template v-for="e in s.exercises" :key="e.exercise_id"><br>{{exercises.find(x=>x.id===e.exercise_id)?.name||e.exercise_id}} {{e.sets}} × {{e.repetitions}}，休息 {{e.rest_seconds}} 秒，阻力：{{e.resistance}}</template></p></div></div><p class="tiny muted">核对背景：{{change.reason}} 这是已保存资料的概述，不代表已验证本次变更的具体生理原因。</p></div><p v-if="!selected.changes.length" class="tiny muted">训练安排没有变化。</p><p class="tiny muted">引用 {{selected.evidence_ids.length}} 条已保存事实 · 基于计划版本 {{selected.base_version}} / 事实修订 {{selected.facts_revision}} · 有效至 {{new Date(selected.expires_at).toLocaleString('zh-CN')}}</p><details v-if="selected.evidence_ids.length"><summary>查看引用的已保存事实</summary><div class="actions"><button v-for="(id,i) in selected.evidence_ids" :key="id" class="btn" @click="viewEvidence(id)">事实 {{i+1}}</button></div><dl v-if="evidence" class="tiny"><template v-for="(value,key) in evidence" :key="key"><dt>{{evidenceLabels[key]||key}}</dt><dd>{{value==null?'未知':typeof value==='object'?JSON.stringify(value):value}}</dd></template></dl></details><div class="actions"><button class="btn primary" :disabled="busy||selected.state!=='pending'" @click="approve">确认整体更新</button><button class="btn" :disabled="busy||selected.state!=='pending'" @click="reject">拒绝这次提案</button></div></div><details v-if="versions.length" class="plan-history"><summary>历史计划（{{versions.length}} 个版本）</summary><div v-for="v in versions" :key="v.id" class="settingsrow"><span class="tiny">版本 {{v.version}} · {{v.start_date}}</span><button class="btn" :disabled="busy||v.version===state?.plan_version" @click="restore(v.version)">提出恢复</button></div></details></section></template>
